#ifndef _VERSION_H
#define _VERSION_H

#include <string>
#include <algorithm>


// These variables are autogenerated and compiled
// into the library by the version.cmake script
extern "C" {
extern const char *GIT_TAG;
extern const char *GIT_BRANCH;
extern const char *GIT_REV;
extern const char *BUILD_TIME;
}

std::string getBuildTime(void)
{
    return std::string(BUILD_TIME);
}

std::string getFwVersion(void)
{
    // Tag is not set
    if ((std::string(GIT_TAG) == "N/A") || (std::string(GIT_TAG) == "")) { // Tag not set, show branch
        return "Develop: " + std::string(GIT_BRANCH) + " @ " + std::string(GIT_REV);
    }

    return std::string(GIT_TAG);
}

std::string getWebUiVersion(void)
{
    const char *fn = "/sdcard/html/version.txt";
    FILE *pFile = fopen(fn, "r");
    if (pFile == NULL) {
        return "?";
    }

    std::string value;
    int c;
    constexpr size_t MAX_VERSION_LENGTH = 256;

    while ((c = fgetc(pFile)) != EOF) {
        if (c == '\n') {
            break;
        }
        value.push_back(static_cast<char>(c));

        if (value.size() > MAX_VERSION_LENGTH) {
            fclose(pFile);
            return "?";
        }
    }
    fclose(pFile);

    if (value.empty()) {
        return "?";
    }

    // Remove any carriage returns (\r) if present
    value.erase(std::remove(value.begin(), value.end(), '\r'), value.end());
    return value;
}


#endif // _VERSION_H
